<template>
  <v-container fluid class="pa-6">
    <header class="d-flex align-center justify-space-between flex-wrap ga-4 mb-6"><div><p class="text-overline">SALES</p><h1 class="text-h4 font-weight-bold">Quotations</h1><p class="text-body-2 text-medium-emphasis mt-2">Prepare offers for leads and customers, and track their response.</p></div><v-btn v-if="auth.can('quotations','create')" color="primary" prepend-icon="mdi-plus" @click="create">New Quotation</v-btn></header>
    <v-row class="mb-5"><v-col v-for="card in summary" :key="card.title" cols="6" md="3"><v-card class="pa-4" rounded="xl" flat><p class="text-caption text-medium-emphasis">{{ card.title }}</p><strong class="text-h5">{{ card.value }}</strong></v-card></v-col></v-row>
    <div class="d-flex ga-3 flex-wrap mb-5"><v-text-field v-model="search" placeholder="Search quotation, recipient or reference" prepend-inner-icon="mdi-magnify" variant="solo" flat hide-details density="compact" style="min-width:240px;flex:1" /><v-select v-model="statusFilter" :items="['All statuses',...statuses]" label="Status" variant="solo" flat hide-details density="compact" style="max-width:220px" /></div>
    <v-alert v-if="error" type="error" variant="tonal" class="mb-4" closable @click:close="error=''">{{ error }}</v-alert>
    <v-data-table :headers="headers" :items="filtered" :loading="loading" class="rounded-xl" hover>
      <template #item.quotation_number="{item}"><v-btn v-if="canDetail(item)" variant="text" class="px-0" @click="open(item)">{{ item.quotation_number }}</v-btn><span v-else>{{ item.quotation_number }}</span></template>
      <template #item.recipient_name="{item}"><strong>{{ item.recipient_name }}</strong><p class="text-caption text-medium-emphasis">{{ item.lead_id?'Lead':item.customer_id?'Customer':'Prospect' }}</p></template>
      <template #item.status="{item}"><v-chip :color="color(item.status)" size="small" variant="tonal">{{ item.status }}</v-chip></template>
      <template #item.total="{item}">{{ money(item.total) }}</template>
      <template #item.actions="{item}"><div class="d-flex align-center ga-1"><v-btn v-if="canDetail(item)" icon="mdi-eye-outline" size="small" variant="text" aria-label="Open quotation" @click="open(item)" /><v-btn v-if="canDetail(item) && auth.canRecord('quotations','edit',item) && !['Accepted','SO'].includes(item.status)" icon="mdi-pencil-outline" size="small" variant="text" aria-label="Edit quotation" @click="edit(item)" /><v-btn v-if="item.status==='Draft' && auth.canRecord('quotations','delete',item)" icon="mdi-delete-outline" size="small" variant="text" color="error" aria-label="Delete quotation" @click="deleting=item" /></div></template>
    </v-data-table>
    <SalesOrderDialog v-model="orderEditing" :quotation-seed="conversionSeed" :order-to-edit="orderEditRecord" :customers="conversionCustomers" :service-types="conversionServices" @saved="orderSaved" />
    <SalesOrderDetail v-model="orderDetailOpen" :order="convertedOrder" @refresh="refreshOrder" @edit="editOrder" />
    <QuotationDialog v-model="editing" :quotation="editRecord" :seed="seed" :initial-lead-id="route.query.lead_id" @saved="saved" />
    <v-dialog v-model="detailOpen" max-width="1500" width="97vw" scrollable><v-card v-if="detail" rounded="xl"><v-card-title class="pa-5 d-flex align-center justify-space-between"><div>{{ detail.quotation_number }} <v-chip :color="color(detail.status)" size="small" class="ml-2">{{ detail.status }}</v-chip></div><v-btn icon="mdi-close" variant="text" @click="detailOpen=false" /></v-card-title><v-card-text>
      <div class="d-flex align-center flex-wrap ga-2 mb-5"><v-btn v-if="auth.canRecord('quotations','edit',detail) && !['Accepted','SO'].includes(detail.status)" variant="tonal" prepend-icon="mdi-pencil-outline" @click="edit(detail)">Edit</v-btn><v-btn v-if="auth.can('quotations','create')" variant="text" prepend-icon="mdi-content-copy" @click="duplicate">Duplicate</v-btn><v-btn v-if="!detail.sales_order_id && ['Draft','Sent','Accepted'].includes(detail.status) && auth.can('sales_orders','create') && auth.canRecord('quotations','edit',detail)" color="primary" variant="tonal" :loading="conversionLoading" @click="convertQuotation">Convert to Sales Order</v-btn><v-btn v-if="detail.sales_order_id && auth.can('sales_orders','read')" variant="tonal" @click="openOrder(detail.sales_order_id)">View Sales Order</v-btn><v-spacer /><v-select v-model="downloadStyle" :items="styles" label="PDF template" variant="outlined" density="compact" hide-details style="max-width:180px" @update:model-value="rememberStyle" /><v-btn prepend-icon="mdi-download-outline" color="primary" variant="tonal" :loading="downloading" @click="download">Quotation PDF</v-btn></div>
      <v-row><v-col cols="12" md="7"><p class="text-caption text-medium-emphasis mb-2">Quote for: {{ detail.lead_id ? 'Existing lead' : detail.customer_id ? 'Existing customer' : 'New prospect' }}</p><h2 class="text-h6">{{ detail.recipient_name }}</h2><p>{{ detail.contact_person }}</p><p>{{ [detail.email,detail.phone].filter(Boolean).join(' · ') }}</p><p>{{ detail.address }}</p><div class="d-flex ga-2 mt-3"><v-btn v-if="detail.lead_id && auth.can('leads')" size="small" variant="text" :to="`/leads/${detail.lead_id}`">Open lead</v-btn><v-btn v-if="detail.customer_id && auth.can('customers')" size="small" variant="text" :to="`/customers/${detail.customer_id}`">Open customer</v-btn></div></v-col><v-col cols="12" md="5"><p>Date: {{ detail.quotation_date }}</p><p>Valid until: {{ detail.valid_until || '—' }}</p><p>Reference: {{ detail.customer_reference || '—' }}</p><p>Branch: {{ detail.branch || '—' }}</p><p>Sales Executive: {{ detail.assigned_staff?.name || (detail.assigned_user_id ? `Staff #${detail.assigned_user_id}` : 'Unassigned') }}</p><p>Saved PDF template: {{ detail.template_style }}</p><p v-if="detail.sent_at">Sent: {{ new Date(detail.sent_at).toLocaleString('en-GB') }}</p></v-col></v-row>
      <v-table class="my-5" density="comfortable">
        <thead><tr><th>Service</th><th>Description</th><th>Qty</th><th>Cost</th><th>Service Charge</th><th>Rate</th><th>Processing Time</th><th>Amount</th></tr></thead>
        <tbody><tr v-for="(item,index) in detail.items" :key="index">
          <td class="py-3"><strong>{{ item.service_name }}</strong></td>
          <td class="quote-text">{{ item.description || '—' }}</td><td>{{ item.quantity }}</td>
          <td class="text-no-wrap">{{ money(item.cost) }}</td><td class="text-no-wrap">{{ money(item.service_charge) }}</td>
          <td class="text-no-wrap">{{ money(item.rate) }}</td><td class="quote-text">{{ item.expected_processing_time || '—' }}</td>
          <td class="text-no-wrap">{{ money(item.total) }}</td>
        </tr></tbody>
      </v-table>
      <div class="quote-totals ml-auto mb-5"><p>Subtotal <strong>{{ money(detail.subtotal) }}</strong></p><p>Discount <strong>{{ money(detail.discount) }}</strong></p><p>VAT ({{ detail.tax_rate }}%) <strong>{{ money(detail.tax_amount) }}</strong></p><p class="text-h6">Total <strong>{{ money(detail.total) }}</strong></p></div>
      <v-row><v-col cols="12" md="6"><h3 class="text-subtitle-1 mb-2">Bank Account Details</h3><p v-for="([key,value]) in Object.entries(detail.bank_details || {}).filter(([,value])=>value)" :key="key" class="text-body-2">{{ key.replaceAll('_',' ') }}: {{ value }}</p><h3 class="text-subtitle-1 mt-4">Payment Terms</h3><p class="quote-text text-body-2">{{ detail.payment_terms || '—' }}</p></v-col><v-col cols="12" md="6"><h3 class="text-subtitle-1 mb-2">Terms and Conditions</h3><p class="quote-text text-body-2">{{ detail.terms || '—' }}</p></v-col></v-row><div v-if="detail.notes" class="mt-4"><h3 class="text-subtitle-1 mb-2">Customer-facing Notes</h3><p class="quote-text">{{ detail.notes }}</p></div><v-alert v-if="detail.internal_remarks" variant="tonal" class="mt-4"><strong>Internal Remarks</strong><p class="quote-text">{{ detail.internal_remarks }}</p></v-alert>
      <div v-if="auth.canRecord('quotations','edit',detail)" class="d-flex flex-wrap ga-2 mt-6"><v-btn v-if="['Draft','Declined','Expired'].includes(detail.status)" color="primary" variant="flat" @click="statusTarget='Sent'">Mark as Sent</v-btn><template v-if="detail.status==='Sent'"><v-btn color="success" variant="tonal" @click="statusTarget='Accepted'">Mark Accepted</v-btn><v-btn color="error" variant="tonal" @click="statusTarget='Declined'">Mark Declined</v-btn><v-btn v-if="detail.valid_until && detail.valid_until<today" variant="text" @click="statusTarget='Expired'">Mark Expired</v-btn></template></div>
    </v-card-text></v-card></v-dialog>
    <v-dialog :model-value="!!statusTarget" @update:model-value="value=>{if(!value)statusTarget=''}" max-width="450"><v-card class="pa-6" rounded="xl"><h3 class="text-h6">Mark quotation {{ statusTarget }}?</h3><p class="my-4">{{ statusTarget==='Sent'?'Record that this quotation has been sent to the recipient. A linked lead will show Quote Sent.':statusTarget==='Accepted'?'Accepted quotations will be locked. Duplicate this quotation if you need to prepare a revised offer.':'Update the quotation response status.' }}</p><div class="d-flex justify-end ga-2"><v-btn :disabled="savingStatus" @click="statusTarget=''">Cancel</v-btn><v-btn color="primary" :loading="savingStatus" @click="updateStatus">Confirm</v-btn></div></v-card></v-dialog>
    <v-dialog :model-value="!!deleting" @update:model-value="value=>{if(!value)deleting=null}" max-width="420"><v-card class="pa-6" rounded="xl"><h3 class="text-h6">Delete draft quotation?</h3><p class="my-3">{{ deleting?.quotation_number }}</p><div class="d-flex justify-end ga-2"><v-btn @click="deleting=null">Cancel</v-btn><v-btn color="error" :loading="deletingBusy" @click="remove">Delete</v-btn></div></v-card></v-dialog>
  </v-container>
</template>
<script setup>
import SalesOrderDialog from '~/components/sales-orders/SalesOrderDialog.vue';import SalesOrderDetail from '~/components/sales-orders/SalesOrderDetail.vue';
import QuotationDialog from '~/components/quotations/QuotationDialog.vue';import {useAuthStore} from '~/stores/auth';import {useUIStore} from '~/stores/ui';
const auth=useAuthStore(),ui=useUIStore(),route=useRoute(),{$api}=useNuxtApp();
const rows=ref([]),loading=ref(false),error=ref(''),search=ref(''),statusFilter=ref('All statuses'),editing=ref(false),editRecord=ref(null),seed=ref(null),detailOpen=ref(false),detail=ref(null),downloadStyle=ref('classic'),downloading=ref(false),statusTarget=ref(''),savingStatus=ref(false),deleting=ref(null),deletingBusy=ref(false);
const styles=['classic','modern','compact','minimal'],statuses=['Draft','Sent','Accepted','Declined','Expired','SO'];
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const headers=[{title:'QUOTATION',key:'quotation_number'},{title:'RECIPIENT',key:'recipient_name'},{title:'DATE',key:'quotation_date'},{title:'VALID UNTIL',key:'valid_until'},{title:'STATUS',key:'status'},{title:'TOTAL',key:'total'},{title:'ACTIONS',key:'actions',sortable:false}];
const summary=computed(()=>[{title:'Quotations',value:rows.value.length},{title:'Draft',value:rows.value.filter(row=>row.status==='Draft').length},{title:'Sent',value:rows.value.filter(row=>row.status==='Sent').length},{title:'Accepted',value:rows.value.filter(row=>row.status==='Accepted').length}]);
const filtered=computed(()=>rows.value.filter(row=>(statusFilter.value==='All statuses'||row.status===statusFilter.value) && [row.quotation_number,row.recipient_name,row.customer_reference].some(value=>String(value||'').toLowerCase().includes(search.value.toLowerCase()))));
const money=value=>'AED '+Number(value || 0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const color=status=>({Draft:'grey',Sent:'info',Accepted:'success',Declined:'error',Expired:'warning',SO:'primary'})[status];
const canDetail=row=>auth.canRecord('quotations','detail',row);
const conversionLoading=ref(false),orderEditing=ref(false),conversionSeed=ref(null),conversionCustomers=ref([]),conversionServices=ref([]),orderDetailOpen=ref(false),convertedOrder=ref(null),orderEditRecord=ref(null);
async function convertQuotation(){conversionLoading.value=true;try{const response=await $api.get(`/quotations/${detail.value.id}/sales-order-draft`);conversionSeed.value=response.data.data.seed;conversionCustomers.value=response.data.data.customers;conversionServices.value=response.data.data.services;orderEditRecord.value=null;detailOpen.value=false;orderEditing.value=true;}catch(e){ui.showError(e.response?.data?.message || 'Unable to prepare the sales order.');}finally{conversionLoading.value=false;}}
async function openOrder(id){try{convertedOrder.value=(await $api.get(`/sales-orders/${id}`)).data.data;orderDetailOpen.value=true;detailOpen.value=false;}catch(e){ui.showError(e.response?.data?.message || 'Unable to open the sales order.');}}
async function orderSaved(order){await load();if(detail.value)detail.value=(await $api.get(`/quotations/${detail.value.id}`)).data.data;if(order?.id && auth.can('sales_orders','read'))await openOrder(order.id);}
async function refreshOrder(){if(convertedOrder.value)await openOrder(convertedOrder.value.id);await load();}
async function editOrder(order){orderEditRecord.value=order;conversionCustomers.value=(await $api.get('/customers',{params:{limit:100,is_active:true}})).data.data;orderDetailOpen.value=false;orderEditing.value=true;}
async function load(){loading.value=true;try{rows.value=(await $api.get('/quotations')).data.data;}catch(e){error.value=e.response?.data?.message || 'Unable to load quotations.';}finally{loading.value=false;}}
function create(){editRecord.value=null;seed.value=null;editing.value=true;}
async function open(row){try{detail.value=(await $api.get(`/quotations/${row.id}`)).data.data;downloadStyle.value=localStorage.getItem(`quotation-template:${auth.user?.tenant_id}:${auth.user?.id}`) || detail.value.template_style || 'classic';detailOpen.value=true;}catch(e){error.value=e.response?.data?.message || 'Unable to open quotation.';}}
async function edit(row){if(!canDetail(row))return;try{editRecord.value=(await $api.get(`/quotations/${row.id}`)).data.data;seed.value=null;detailOpen.value=false;editing.value=true;}catch(e){error.value=e.response?.data?.message || 'Unable to edit quotation.';}}
function duplicate(){seed.value=JSON.parse(JSON.stringify(detail.value));editRecord.value=null;detailOpen.value=false;editing.value=true;}
async function saved(row){ui.showSuccess('Quotation saved as draft.');await load();if(canDetail(row))await open(row);}
function rememberStyle(){localStorage.setItem(`quotation-template:${auth.user?.tenant_id}:${auth.user?.id}`,downloadStyle.value);}
async function download(){downloading.value=true;try{const {data}=await $api.get(`/quotations/${detail.value.id}/pdf`,{params:{template:downloadStyle.value},responseType:'blob'});const url=URL.createObjectURL(data);const link=document.createElement('a');link.href=url;link.download=detail.value.quotation_number+'.pdf';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{ui.showError('Unable to download quotation.');}finally{downloading.value=false;}}
async function updateStatus(){savingStatus.value=true;try{await $api.post(`/quotations/${detail.value.id}/status`,{status:statusTarget.value});statusTarget.value='';await open(detail.value);await load();ui.showSuccess('Quotation status updated.');}catch(e){ui.showError(e.response?.data?.message || 'Unable to update status.');}finally{savingStatus.value=false;}}
async function remove(){deletingBusy.value=true;try{await $api.delete(`/quotations/${deleting.value.id}`);deleting.value=null;await load();ui.showSuccess('Draft quotation deleted.');}catch(e){ui.showError(e.response?.data?.message || 'Unable to delete quotation.');}finally{deletingBusy.value=false;}}
async function openLinkedQuotation(){const row=rows.value.find(item=>String(item.id)===String(route.query.quotation_id));if(row && canDetail(row))await open(row);}
useCreateAction('quotations',create);onMounted(async()=>{await load();await openLinkedQuotation();});watch(()=>route.query.quotation_id,openLinkedQuotation);
</script>
<style scoped>.quote-text{white-space:pre-wrap;overflow-wrap:anywhere}.quote-totals{max-width:350px}.quote-totals p{display:flex;justify-content:space-between;gap:20px;padding:5px 0}</style>
